/**
 * Standalone Bundled Markdown Parser for Cognitive Coach Webview.
 * Provides offline Markdown rendering without external CDN calls.
 */
(function(global) {
  'use strict';

  function escapeHtml(text) {
    return (text || '')
      .replace(/&/g, '&amp;')
      .replace(/</g, '&lt;')
      .replace(/>/g, '&gt;')
      .replace(/"/g, '&quot;')
      .replace(/'/g, '&#39;');
  }

  function parseMarkdown(src) {
    if (!src) return '';
    let out = String(src);

    // Code blocks with language specification
    out = out.replace(/```([a-zA-Z0-9_\-\+]*)\n([\s\S]*?)```/g, function(_, lang, code) {
      const cleanLang = lang ? lang.trim() : '';
      return '<pre class="code-block"><code class="language-' + cleanLang + '">' + escapeHtml(code.trim()) + '</code></pre>';
    });

    // Inline code
    out = out.replace(/`([^`]+)`/g, function(_, code) {
      return '<code>' + escapeHtml(code) + '</code>';
    });

    // Headers (#, ##, ###)
    out = out.replace(/^### (.*$)/gim, '<h3>$1</h3>');
    out = out.replace(/^## (.*$)/gim, '<h2>$1</h2>');
    out = out.replace(/^# (.*$)/gim, '<h1>$1</h1>');

    // Bold & Italics
    out = out.replace(/\*\*([^*]+)\*\*/g, '<strong>$1</strong>');
    out = out.replace(/__([^_]+)__/g, '<strong>$1</strong>');
    out = out.replace(/\*([^*]+)\*/g, '<em>$1</em>');
    out = out.replace(/_([^_]+)_/g, '<em>$1</em>');

    // Unordered list items (- or *)
    out = out.replace(/^\s*[\-\*]\s+(.*$)/gim, '<li>$1</li>');
    out = out.replace(/(<li>.*<\/li>)/gim, '<ul>$1</ul>');

    // Line breaks to paragraphs
    const paragraphs = out.split(/\n\n+/);
    out = paragraphs.map(function(p) {
      p = p.trim();
      if (!p) return '';
      if (/^<(h[1-6]|ul|ol|pre|blockquote)/i.test(p)) return p;
      return '<p>' + p.replace(/\n/g, '<br>') + '</p>';
    }).join('');

    return out;
  }

  global.marked = {
    parse: parseMarkdown
  };
})(typeof window !== 'undefined' ? window : this);
